package com.employee.management.service;
import com.employee.management.dto.PayrollRequest; import com.employee.management.entity.*; import com.employee.management.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.*; import java.util.*;
@Service public class PayrollService {
 private final PayrollRecordRepository repo; private final EmployeeRepository employees; private final AttendanceRepository attendance; private final UserRepository users;
 public PayrollService(PayrollRecordRepository r,EmployeeRepository e,AttendanceRepository a,UserRepository u){repo=r;employees=e;attendance=a;users=u;}
 @Transactional public PayrollRecord generate(PayrollRequest r,String username){Employee e=employees.findById(r.employeeId()).orElseThrow();String requested=r.month();int m=requested==null||requested.isBlank()?LocalDate.now().getMonthValue():(requested.contains("-")?Integer.parseInt(requested.substring(requested.indexOf('-')+1)):Integer.parseInt(requested)),y=r.year()==null?LocalDate.now().getYear():(requested!=null&&requested.contains("-")?Integer.parseInt(requested.substring(0,requested.indexOf('-'))):r.year());PayrollRecord p=repo.findByEmployee_IdAndPayrollMonthAndPayrollYear(e.getId(),m,y).orElseGet(PayrollRecord::new);p.setEmployee(e);p.setPayrollMonth(m);p.setPayrollYear(y);BigDecimal basic=e.getBasicSalary()==null?BigDecimal.ZERO:e.getBasicSalary();p.setBasicSalary(basic);p.setTotalAllowances(basic.multiply(BigDecimal.valueOf(.4)));p.setTotalDeductions(basic.multiply(BigDecimal.valueOf(.12)));p.setNetSalary(basic.add(p.getTotalAllowances()).subtract(p.getTotalDeductions()));p.setWorkingDays(0);users.findByUsername(username).ifPresent(p::setGeneratedBy);return repo.save(p);}
 public List<PayrollRecord> all(Long employeeId){return employeeId==null?repo.findAll():repo.findByEmployee_IdOrderByPayrollYearDescPayrollMonthDesc(employeeId);}
}
